-- =====================================================================
-- Oficinas Corporativas: comunicar que es una oficina completa, llave en
-- mano (inmueble, adecuacion, mobiliario, personalizacion y operacion),
-- no coworking. Galeria de un proyecto real en lugar de las imagenes IA.
-- =====================================================================
UPDATE blocks SET value_es='Tu oficina completa, llave en mano: elegimos el inmueble, lo adecuamos, lo amueblamos y lo operamos para tu empresa.', value_en='Your entire office, turnkey: we find the property, fit it out, furnish it and run it for your company.' WHERE page_id=(SELECT id FROM pages WHERE slug='oficinas-corporativas') AND section='hero' AND skey='lead';
-- La etiqueta sobre el titulo, el segundo parrafo y el plazo pasan al texto de la seccion siguiente.
UPDATE blocks SET value_es='', value_en='' WHERE page_id=(SELECT id FROM pages WHERE slug='oficinas-corporativas') AND section='hero' AND skey='chip';
UPDATE blocks SET value_es='', value_en='' WHERE page_id=(SELECT id FROM pages WHERE slug='oficinas-corporativas') AND section='hero' AND skey='lead2';
UPDATE blocks SET value_es='', value_en='' WHERE page_id=(SELECT id FROM pages WHERE slug='oficinas-corporativas') AND section='hero' AND skey='plazo';
